-- Jobs and industries: who a resource helps and in which field (src/lib/taxonomy.ts JOBS, INDUSTRIES).
-- Adds resources.jobs and resources.industries, lets the Curator write them through patch_resources, and
-- backfill. Published on 2026-10-25 and labelled software development only (673 resources): the default below.
update public.resources
   set jobs = '{engineering}'
 where status = 'published' and jobs = '{}' and first_seen_at < '2026-10-25T09:00:00Z';
-- the others (549): slug -> "job[,job]|industry[,industry]"
